begin;

-- Internal command receipts and static wording are never exposed through the Data API.
create schema if not exists journey_private;
revoke all on schema journey_private from public, anon, authenticated;
create table journey_private.task_catalog (
  lane_key text not null,
  step_key text not null,
  definition jsonb not null,
  primary key (lane_key, step_key)
);
create table journey_private.command_receipts (
  transaction_id uuid not null references public.transactions(id) on delete cascade,
  command_id uuid not null,
  actor_id uuid not null,
  request jsonb not null,
  result jsonb not null,
  created_at timestamptz not null default now(),
  primary key (transaction_id, command_id)
);
-- Minimal durable change feed; notes, work packets and private evidence never enter it.
create table journey_private.task_events (
  transaction_id uuid not null references public.transactions(id) on delete cascade,
  command_id uuid not null,
  revision bigint not null,
  lane_key text not null,
  step_key text not null,
  previous_status text not null,
  status text not null,
  created_at timestamptz not null default now(),
  primary key (transaction_id, command_id)
);
alter table journey_private.task_catalog enable row level security;
alter table journey_private.command_receipts enable row level security;
alter table journey_private.task_events enable row level security;
revoke all on all tables in schema journey_private from public, anon, authenticated;
