create or replace function public.bridge_update_attorney_workflow_step_v4(
  p_transaction_id uuid,
  p_lane_key text,
  p_step_id uuid,
  p_status text,
  p_command_id uuid,
  p_expected_step_updated_at timestamptz,
  p_note text default '',
  p_visibility text default 'internal',
  p_work_packet jsonb default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := auth.uid();
  v_request jsonb;
  v_receipt journey_private.command_receipts%rowtype;
  v_step public.transaction_subprocess_steps%rowtype;
  v_result jsonb;
  v_definition jsonb;
  v_revision bigint;
  v_lane_snapshots jsonb;
  v_plan jsonb;
  v_legal_progress jsonb;
  v_lane_progress jsonb;
begin
  if v_actor is null or not exists (
    select 1 from public.profiles where id = v_actor and lower(coalesce(role,'')) in ('attorney','conveyancer')
  ) then raise exception 'Attorney authentication is required.' using errcode = '42501'; end if;
  if p_lane_key is null or p_lane_key not in ('transfer','bond','cancellation')
    or p_command_id is null then raise exception 'Invalid journey command.' using errcode = '22023'; end if;
  if not public.bridge_can_mutate_attorney_lane(p_transaction_id, p_lane_key || '_attorney', 'workflow')
  then raise exception 'You do not have permission to update this attorney workflow lane.' using errcode = '42501'; end if;
  if not public.bridge_can_mutate_attorney_lane(p_transaction_id, p_lane_key || '_attorney',
    case when p_visibility = 'internal' then 'internal_notes' else 'shared_updates' end)
  then raise exception 'You do not have permission to publish this update.' using errcode = '42501'; end if;

  -- Match the legacy publisher's advisory-before-matter order to avoid inversion.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_transaction_id::text || ':' || p_lane_key,0));
  -- Same row lock order as the existing mutation: matter, then lane, then task.
  perform 1 from public.transactions where id = p_transaction_id for update;
  if not found then raise exception 'Matter not found.' using errcode = 'P0002'; end if;
  v_request := jsonb_build_object('lane',p_lane_key,'step',p_step_id,'status',p_status,
    'expectedUpdatedAt',p_expected_step_updated_at,'note',p_note,'visibility',p_visibility,'workPacket',p_work_packet);
  select * into v_receipt from journey_private.command_receipts
    where transaction_id = p_transaction_id and command_id = p_command_id;
  if found then
    if v_receipt.actor_id <> v_actor or v_receipt.request <> v_request
    then raise exception 'Command id was already used for a different update.' using errcode = '22023'; end if;
    return v_receipt.result || jsonb_build_object('replayed',true);
  end if;

  select step.* into v_step from public.transaction_subprocess_steps step
    join public.transaction_subprocesses lane on lane.id = step.subprocess_id
    where step.id = p_step_id and lane.transaction_id = p_transaction_id and lane.process_type = p_lane_key;
  if not found then raise exception 'Workflow step not found.' using errcode = 'P0002'; end if;
  if v_step.updated_at is distinct from p_expected_step_updated_at
  then raise exception 'This task changed. Refresh before saving again.' using errcode = '40001'; end if;
  select definition into v_definition from journey_private.task_catalog
    where lane_key = p_lane_key and step_key = v_step.step_key;
  if not found then raise exception 'Unknown task catalog key. Refresh the workflow.' using errcode = '22023'; end if;
  if p_visibility = 'client_visible' and not coalesce((v_definition ->> 'clientVisibleAllowed')::boolean,false)
  then raise exception 'This task cannot publish a client-visible note.' using errcode = '42501'; end if;

  v_result := public.bridge_update_attorney_workflow_step_v3(
    p_transaction_id,p_lane_key,p_step_id,p_status,p_note,p_visibility,p_work_packet);

  -- Preserve the existing legacy projection, but inside the same transaction.
  -- Legacy vocabulary cannot represent external completion / N/A; never coerce them.
  if p_status not in ('completed_externally','not_applicable') then
    perform public.bridge_publish_transaction_shared_progress_phase2(
      p_transaction_id, v_definition ->> 'processKey', v_definition ->> 'processLabel',
      v_step.step_key, p_status, v_definition ->> 'ownerRole', p_status = 'blocked',
      case p_status when 'blocked' then 'This step is blocked while the responsible team resolves the issue.'
        when 'waiting' then 'Awaiting action from the responsible party.' else '' end,
      '', p_visibility, v_definition #>> '{professional,title}', v_definition #>> '{professional,description}',
      v_definition #>> '{client,title}', v_definition #>> '{client,description}',
      'attorney_workflow_step', p_step_id::text);
    -- The legacy publisher writes a display summary. Restore canonical lifecycle authority.
    perform public.bridge_recompute_matter_lifecycle_from_attorney_workflows(p_transaction_id,v_actor,null,null);
  end if;

  -- Existing triggers may advance this token too: monotonic, not necessarily contiguous.
  insert into public.transaction_refresh_signals(transaction_id,version,changed_at)
    values(p_transaction_id,1,now())
  on conflict(transaction_id) do update set
    version = public.transaction_refresh_signals.version + 1, changed_at = excluded.changed_at
  returning version into v_revision;

  -- A coherent, internal snapshot for the shared-plan adapter. No notes or documents.
  select routing_profile_json -> 'workflowPlan' into v_plan
    from public.transactions where id = p_transaction_id;
  select coalesce(jsonb_object_agg(lane.process_type, jsonb_build_object('steps',
    (select coalesce(jsonb_agg(jsonb_build_object('id',step.id,'step_key',step.step_key,
      'status',step.status,'revision',v_revision,'updated_at',step.updated_at)
      order by step.sort_order,step.step_key),'[]'::jsonb)
     from public.transaction_subprocess_steps step where step.subprocess_id = lane.id)
  )), '{}'::jsonb) into v_lane_snapshots
  from public.transaction_subprocesses lane
  where lane.transaction_id = p_transaction_id and lane.process_type in ('transfer','bond','cancellation');

  -- Count the plan, not only existing rows. N/A is excluded; external completion
  -- counts as completed. An empty applicable denominator is unknown, not 100%.
  with planned as (
    select lp ->> 'laneKey' lane_key, k.step_key
    from jsonb_array_elements(coalesce(v_plan -> 'lanes','[]'::jsonb)) lp
    cross join lateral jsonb_array_elements_text(lp -> 'stepKeys') k(step_key)
    where v_plan ->> 'status' = 'active'
    union all
    select l.process_type,s.step_key from public.transaction_subprocesses l
    join public.transaction_subprocess_steps s on s.subprocess_id = l.id
    where l.transaction_id = p_transaction_id and l.process_type in ('transfer','bond','cancellation')
      and coalesce(v_plan ->> 'status','') <> 'active'
  ), outcomes as (
    select p.lane_key,coalesce(s.status,'not_started') status from planned p
    left join public.transaction_subprocesses l on l.transaction_id = p_transaction_id and l.process_type = p.lane_key
    left join public.transaction_subprocess_steps s on s.subprocess_id = l.id and s.step_key = p.step_key
  ), totals as (
    select lane_key, count(*) filter(where status <> 'not_applicable') applicable,
      count(*) filter(where status in ('completed','completed_externally')) completed,
      count(*) filter(where status = 'not_applicable') excluded
    from outcomes group by grouping sets ((lane_key),())
  ), progress as (
    select lane_key,jsonb_build_object('applicableCount',applicable,'completedCount',completed,
      'notApplicableCount',excluded,'percent',round(100.0*completed/nullif(applicable,0))) value
    from totals
  )
  select (select value from progress where lane_key is null),
    (select coalesce(jsonb_object_agg(lane_key,value),'{}'::jsonb) from progress where lane_key is not null)
  into v_legal_progress,v_lane_progress;

  insert into journey_private.task_events(transaction_id,command_id,revision,lane_key,step_key,previous_status,status)
    values(p_transaction_id,p_command_id,v_revision,p_lane_key,v_step.step_key,v_step.status,p_status);
  v_result := v_result || jsonb_build_object(
    'commandId',p_command_id,'revision',v_revision,'replayed',false,
    'completionPercent',v_lane_progress -> p_lane_key -> 'percent',
    'committedSnapshot',jsonb_build_object('transactionId',p_transaction_id,'revision',v_revision,
      'workflowPlan',v_plan,'laneSnapshots',v_lane_snapshots,'legalProgress',v_legal_progress,'laneProgress',v_lane_progress));
  insert into journey_private.command_receipts(transaction_id,command_id,actor_id,request,result)
    values(p_transaction_id,p_command_id,v_actor,v_request,v_result);
  return v_result;
end;
$$;

-- Only the versioned entry point is callable by browsers. v3 remains the internal
-- implementation, avoiding a second copy of lifecycle and audit logic.
revoke all on function public.bridge_update_attorney_workflow_step_v4(uuid,text,uuid,text,uuid,timestamptz,text,text,jsonb) from public,anon;
grant execute on function public.bridge_update_attorney_workflow_step_v4(uuid,text,uuid,text,uuid,timestamptz,text,text,jsonb) to authenticated;
do $revoke$
declare f record;
begin
  for f in select oid::regprocedure as signature from pg_proc
    where pronamespace = 'public'::regnamespace
      and proname in ('bridge_update_attorney_workflow_step','bridge_update_attorney_workflow_step_v2','bridge_update_attorney_workflow_step_v3')
  loop execute format('revoke all on function %s from public, anon, authenticated',f.signature); end loop;
end;
$revoke$;
notify pgrst, 'reload schema';
commit;
